-- 更新客户授信申请表单 schema：营业执照字段改为条件必填
-- 当客户档案已有营业执照时（_hasExistingLicense=yes），上传字段非必填
UPDATE oa_form_types
SET form_schema = '{"fields":[{"key":"customer","label":"客户","type":"erp_customer","required":true,"searchApi":"erp_customers","autoFill":{"contactName":"contactName","contactTel":"contactTel"}},{"key":"contactName","label":"联系人","type":"text","required":false,"disabled":true},{"key":"contactTel","label":"联系电话","type":"text","required":false,"disabled":true},{"key":"creditType","label":"授信类型","type":"select","required":true,"options":[{"value":"payment_period","label":"账期"},{"value":"rolling_order","label":"滚单"},{"value":"hold_order","label":"压单"}]},{"key":"maxOverdueDays","label":"最大欠款天数","type":"number","required":true,"min":1,"suffix":"天","visibleWhen":{"field":"creditType","operator":"==","value":"payment_period"},"requiredWhen":{"field":"creditType","operator":"==","value":"payment_period"}},{"key":"rollingMaxOverdueDays","label":"最大欠款天数","type":"number","required":true,"min":1,"suffix":"天","visibleWhen":{"field":"creditType","operator":"==","value":"rolling_order"},"requiredWhen":{"field":"creditType","operator":"==","value":"rolling_order"}},{"key":"rollingMaxOverdueOrders","label":"最大欠款单数","type":"number","required":true,"min":1,"suffix":"单","visibleWhen":{"field":"creditType","operator":"==","value":"rolling_order"},"requiredWhen":{"field":"creditType","operator":"==","value":"rolling_order"}},{"key":"holdSettlementOrders","label":"选择压单结算单","type":"erp_settlement_order","required":true,"searchApi":"erp_settlement_orders","multiple":true,"cascadeFrom":"customer","visibleWhen":{"field":"creditType","operator":"==","value":"hold_order"},"requiredWhen":{"field":"creditType","operator":"==","value":"hold_order"}},{"key":"businessLicensePhotos","label":"客户营业执照","type":"photo","required":false,"requiredWhen":{"field":"_hasExistingLicense","operator":"==","value":"no"},"maxCount":3},{"key":"remark","label":"备注","type":"textarea","required":false,"maxLength":500}]}',
  updated_at = NOW()
WHERE code = 'customer_credit';
